use std::sync::atomic::{AtomicPtr, Ordering};

fn replace(target: &AtomicPtr<i32>, val: &mut i32) -> *mut i32 {
    let raw = ⟦slot1⟧;
    target.⟦slot2⟧(raw, Ordering::Relaxed)
}

fn main() {
    let (mut old, mut new) = (100, 200);
    let ptr = AtomicPtr::new(&mut old);
    let prev = replace(&ptr, &mut new);
    unsafe { assert_eq!((*prev, *ptr.load(Ordering::Relaxed)), (100, 200)); }
}
